import { approve_rejct_unverified_loc } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    approvalLocation: Boolean,
    rowInfo: Object
  },
  data() {
    return {
      loading: false,
      loadingapprove: false
    };
  },
  watch: {
    approvalLocation: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation(val) {
      if (val == "APPROVED") {
        this.loadingapprove = true;
      } else {
        this.loading = true;
      }
      try {
        let result = await API.graphql(graphqlOperation(approve_rejct_unverified_loc, {
          input: {
            location_id: this.rowInfo.location_id,
            approval_status: val,
            location_verification_status: val == "APPROVED" ? "VERIFIED" : "UNVERIFIED"
          }
        }));
        this.loading = false;
        this.loadingapprove = false;
        var response = JSON.parse(result.data.approve_rejct_unverified_loc);
        this.loading = false;
        this.loadingapprove = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.loadingapprove = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
